mapper.select:
SELECT COUNT(*)
FROM coupon_give_error_log c
LEFT JOIN kaquan_discount_cards k ON c.card_id = k.card_id
WHERE c.give_id = #{giveId}
AND c.company_id = #{companyId}

SELECT c.give_log_id, c.give_id, c.uid, c.company_id, c.card_id, c.note, c.created, c.updated, k.title AS title
FROM coupon_give_error_log c
LEFT JOIN kaquan_discount_cards k ON c.card_id = k.card_id
WHERE c.give_id = #{giveId}
AND c.company_id = #{companyId}
ORDER BY c.created DESC
LIMIT #{limit} OFFSET #{offset}
